package org.com.sharekhan.analysis;
import org.junit.jupiter.api.Test;import org.com.sharekhan.service.SharekhanHistoricalService.HistoricalCandle;
import java.time.*;import java.math.BigDecimal;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class VcpResearchTest {
 final LocalDate day=LocalDate.of(2026,10,30);final SwingSessions calendar=new SwingSessions();
 List<HistoricalCandle> bars(){
  var days=new ArrayList<LocalDate>();for(LocalDate d=day;days.size()<253;d=d.minusDays(1))if(d.getDayOfWeek().getValue()<6&&(!calendar.supported(d)||calendar.regular(d)))days.add(d);Collections.reverse(days);
  int[] points={0,69,70,80,90,100,110,116,119};double[] values={115,115,120,100,119,110,118,114,117};var rows=new ArrayList<HistoricalCandle>();
  for(int i=0;i<253;i++){double price=50+i*.45;long volume=10_000_000L;if(i>=133){int n=i-133;price=115;for(int p=1;p<points.length;p++)if(n>=points[p-1]&&n<=points[p]){price=values[p-1]+(values[p]-values[p-1])*(n-points[p-1])/(points[p]-points[p-1]);break;}volume=n>=100?3_000_000L:10_000_000L;}rows.add(new HistoricalCandle(days.get(i),LocalTime.MIDNIGHT,price-.1,price+.2,price-.2,price,volume));}return rows;
 }
 StockDailyHistoryStore.Saved saved(String symbol,String id){return new StockDailyHistoryStore.Saved(symbol,id,new BigDecimal(".05"),Instant.parse("2026-11-01T12:00:00Z"),bars());}
 VcpResearchService service(SavedDailyAnalysis daily,NiftyDailyBenchmark b){return new VcpResearchService(daily,b,calendar,Clock.fixed(Instant.parse("2026-11-01T17:00:00Z"),StockAnalysisService.IST));}
 Map<LocalDate,Double> closes(){var m=new TreeMap<LocalDate,Double>();for(var c:bars())m.put(c.date(),100.0);return m;}
 @Test void confirmsShrinkingSwingsAndProducesConservativePlan(){var s=service(mock(SavedDailyAnalysis.class),mock(NiftyDailyBenchmark.class));var i=s.validate(saved("DEMO","10"),day);assertThat(i.problem()).isNull();var r=s.evaluate(i,day,calendar.next(day),20.0,99.0);assertThat(r.validPattern()).as(r.reason()).isTrue();assertThat(r.contractions()).hasSizeGreaterThanOrEqualTo(2);assertThat(r.trendPassed()).isEqualTo(7);assertThat(r.plan()).as(r.reason()).isNotNull();var p=r.plan();assertThat(p.target1()).isGreaterThanOrEqualTo(p.maxEntry()+2*p.riskPerShare());assertThat(p.target2()).isGreaterThanOrEqualTo(p.maxEntry()+3*p.riskPerShare());assertThat(p.riskPercent()).isLessThanOrEqualTo(8);assertThat(p.maxEntry()).isLessThanOrEqualTo(r.pivot()*1.02);}
 @Test void alignedRelativeStrengthNeedsAllFourDatesAndNoPartialFallback(){var map=closes();Double before=VcpResearchService.relativeStrength(bars(),map);assertThat(before).isPositive();map.remove(bars().get(0).date());assertThat(VcpResearchService.relativeStrength(bars(),map)).isNull();map=closes();map.remove(day);assertThat(VcpResearchService.relativeStrength(bars(),map)).isNull();}
 @Test void ranksTiesEquallyAndDoesNotInventRankSpread(){var ranks=VcpResearchService.percentiles(Map.of("A",1.0,"B",1.0,"C",1.0));assertThat(ranks.values()).containsOnly(50.0);ranks=VcpResearchService.percentiles(Map.of("A",-1.0,"B",0.0,"C",1.0));assertThat(ranks).containsEntry("A",0.0).containsEntry("C",100.0);}
 @Test void futurePricesCannotChangeHistoricalEvidence(){var s=service(mock(SavedDailyAnalysis.class),mock(NiftyDailyBenchmark.class));var input=saved("DEMO","10");var before=s.evaluate(s.validate(input,day),day,calendar.next(day),20.0,99.0);var rows=bars();rows.add(new HistoricalCandle(day.plusDays(1),LocalTime.MIDNIGHT,500,1000,1,900,50_000_000L));var after=s.evaluate(s.validate(new StockDailyHistoryStore.Saved("DEMO","10",input.tick(),input.capturedAt(),rows),day),day,calendar.next(day),20.0,99.0);assertThat(after).isEqualTo(before);}
 @Test void missingHistoryBadVolumeAndDiscontinuityFailClosed(){var s=service(mock(SavedDailyAnalysis.class),mock(NiftyDailyBenchmark.class));var input=saved("DEMO","10");assertThat(s.validate(new StockDailyHistoryStore.Saved("DEMO","10",input.tick(),input.capturedAt(),bars().subList(1,253)),day).problem()).contains("253");var rows=bars();rows.set(252,new HistoricalCandle(day,LocalTime.MIDNIGHT,117,118,116,117,-1L));assertThat(s.validate(new StockDailyHistoryStore.Saved("DEMO","10",input.tick(),input.capturedAt(),rows),day).problem()).contains("OHLCV");rows=bars();var c=rows.get(200);rows.set(200,new HistoricalCandle(c.date(),c.time(),200,202,198,200,10_000_000L));assertThat(s.validate(new StockDailyHistoryStore.Saved("DEMO","10",input.tick(),input.capturedAt(),rows),day).problem()).contains("discontinuity");}
 @Test void patternInvalidatesNoncontractingOrStaleDepths(){var a=new VcpPattern.Contraction(day.minusDays(30),day.minusDays(20),120,100,16.66,10,70,80);var b=new VcpPattern.Contraction(day.minusDays(10),day.minusDays(4),119,100,15.96,6,110,116);assertThat(VcpPattern.validate(List.of(a,b),120).valid()).isFalse();assertThat(VcpPattern.validate(List.of(a),120).valid()).isFalse();}
 @Test void missingRsNeverPublishesPlanEvenWithValidStructure(){var s=service(mock(SavedDailyAnalysis.class),mock(NiftyDailyBenchmark.class));var r=s.evaluate(s.validate(saved("DEMO","10"),day),day,calendar.next(day),null,null);assertThat(r.plan()).isNull();assertThat(r.reason()).contains("benchmark");}
 VcpResearchService universe(boolean cautious,boolean benchmarkMissing,boolean collision){
  var daily=mock(SavedDailyAnalysis.class);var b=mock(NiftyDailyBenchmark.class);var members=new ArrayList<StockDailyHistoryStore.Member>();
  for(int i=0;i<200;i++){String symbol="DEMO"+i;members.add(new StockDailyHistoryStore.Member(symbol,"INE"+i,day));var data=bars();if(i>0){for(int n=0;n<133;n++){var c=data.get(n);double price=90+n*.1;data.set(n,new HistoricalCandle(c.date(),c.time(),price-.1,price+.2,price-.2,price,c.volume()));}if(cautious)data.set(252,new HistoricalCandle(day,LocalTime.MIDNIGHT,90,91,89,90,3_000_000L));}when(daily.read(symbol,day)).thenReturn(new StockDailyHistoryStore.Saved(symbol,collision&&i<2?"100":String.valueOf(100+i),new BigDecimal(".05"),Instant.now(),data));}
  when(daily.members()).thenReturn(members);var refs=closes();if(benchmarkMissing)refs.remove(day);when(b.read(day)).thenReturn(new NiftyDailyBenchmark.Snapshot("NIFTY 50","DHAN","13",refs,0));return service(daily,b);
 }
 @Test void fullReportPublishesOnlyGatedPlansAndCaches(){var s=universe(false,false,false);var r=s.report();assertThat(r.status()).isEqualTo("READY");assertThat(r.stocks()).anyMatch(row->row.plan()!=null);assertThat(s.report()).isSameAs(r);}
 @Test void marketGateWithholdsPlansButRetainsEvidence(){var r=universe(true,false,false).report();assertThat(r.status()).isEqualTo("MARKET_CAUTION");assertThat(r.stocks()).allMatch(row->row.plan()==null);assertThat(r.stocks()).anyMatch(row->row.validPattern()&&row.status().equals("WATCH_ONLY"));}
 @Test void missingBenchmarkBlocksEveryPlanAndIdentityCollisionsStayUnavailable(){var r=universe(false,true,false).report();assertThat(r.status()).isEqualTo("BENCHMARK_INCOMPLETE");assertThat(r.rsPopulation()).isZero();assertThat(r.stocks()).allMatch(row->row.plan()==null);r=universe(false,false,true).report();assertThat(r.coveredCount()).isEqualTo(198);assertThat(r.stocks().stream().filter(row->row.status().equals("UNAVAILABLE")).count()).isEqualTo(2);}

}
